// PNCP TIC — parâmetros de pesquisa.
// UFs OU UASG (exclusivos). Prazo obrigatório em dias.
// Listas opcionais, separadas por vírgulas ou arrays:
// termosFortes, termosContextuais, contextosTecnologicos, termosExclusao.
// Sem valores fixos de prazo ou palavras-chave.
// Modalidades e pesos de pontuação permanecem fixos.

const iniciadoEmMs=Date.now();
const query={...($json.body && typeof $json.body==='object' && !Array.isArray($json.body)?$json.body:{}),...($json.query??{})};
const TODAS_UFS=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];

function lista(v){
  if(Array.isArray(v)) return v.flatMap(x=>String(x??'').split(',')).map(x=>x.trim()).filter(Boolean);
  return String(v??'').split(',').map(x=>x.trim()).filter(Boolean);
}

// UASG aceita um código ou lista separada por vírgulas. Preserva zeros iniciais.
const uasgsEntrada=query.uasgs??query.uasg??query.UASG;
const uasgs=[...new Set(lista(uasgsEntrada).flatMap(v=>String(v??'').split(',')).map(v=>v.trim()).filter(Boolean))];
const uasgsInvalidas=uasgs.filter(v=>!/^\d{6}$/.test(v));
const erroFiltroUasg=uasgsInvalidas.length
  ? 'UASG inválida: '+uasgsInvalidas.join(', ')+'. Informe códigos com exatamente 6 dígitos, separados por vírgulas quando houver mais de um.'
  : null;

// Busca exata: UASG + numeroCompra (NNNNN/AAAA ou idCompra com 17 digitos).
// Tem prioridade absoluta sobre UF, prazo, modalidade, status e termos TIC.
const numeroCompraEntrada=query.numeroCompra??query.numero_compra??query.numeroDaCompra;
const numeroCompra=String(numeroCompraEntrada??'').trim();
const modoBuscaCompra=numeroCompra.length>0;
let erroCompra=null;
let idsCompra=[];
if(modoBuscaCompra){
  if(uasgs.length!==1 || erroFiltroUasg){
    erroCompra='Para pesquisa por numeroCompra, informe exatamente uma UASG valida com 6 digitos.';
  } else if(/^\d{17}$/.test(numeroCompra)){
    if(!numeroCompra.startsWith(uasgs[0]))erroCompra='O identificador da compra nao corresponde a UASG informada.';
    else idsCompra=[numeroCompra];
  } else {
    const match=numeroCompra.match(/^(\d{1,5})\s*\/\s*(20\d{2})$/);
    if(!match){
      erroCompra='Informe numeroCompra no formato 90012/2026 (numero/ano, ate 5 digitos) ou o idCompra de 17 digitos. O ano e obrigatorio.';
    }else{
      // O idCompra do Compras.gov.br tem 6 digitos de UASG + 2 de modalidade
      // + 5 de numero + 4 de ano. Sem modalidade externa, consultamos
      // os codigos candidatas na API oficial e verificamos os retornos.
      const numero5=match[1].padStart(5,'0');
      const ano=match[2];
      const modalidadesId=['05','06','07','03','04','02','01','08','09','10','11','12'];
      idsCompra=modalidadesId.map(mod=>uasgs[0]+mod+numero5+ano);
    }
  }
}

const prazoEntrada=query.prazo;
const prazo=Number(prazoEntrada);
const prazoValido=prazoEntrada!==undefined && prazoEntrada!==null && String(prazoEntrada).trim()!=='' && Number.isInteger(prazo) && prazo>=1 && prazo<=365;
const erroPrazo=prazoValido?null:'Informe prazo em dias: um número inteiro entre 1 e 365, sem valor padrão.';
const termosFortes=[...new Set(lista(query.termosFortes))];
const termosContextuais=[...new Set(lista(query.termosContextuais))];
const contextosTecnologicos=[...new Set(lista(query.contextosTecnologicos))];
const termosExclusao=[...new Set(lista(query.termosExclusao))];
const erroTermos=termosFortes.length || (termosContextuais.length && contextosTecnologicos.length)
  ? null : 'Informe termosFortes ou a combinação termosContextuais + contextosTecnologicos para classificar as contratações.';

const ufsParametro=query.ufs??query.uf??query.UFs??query.UFS;
const temUfs=lista(ufsParametro).some(v=>String(v??'').trim()!=='');
const erroAlternativas=uasgs.length && temUfs
  ? 'Informe apenas um filtro: UFs (ufs) ou UASG (uasg/uasgs). Os dois não podem ser usados juntos.' : null;
const ufsInformadas=lista(ufsParametro).map(v=>v.toUpperCase());
const ufsInvalidas=ufsInformadas.filter(v=>!TODAS_UFS.includes(v)&&!['TODAS','BR','*'].includes(v));
const erroLocalidade=!uasgs.length&&!temUfs?'Informe UFs (ufs) ou UASG (uasg/uasgs). Não há UF padrão.':ufsInvalidas.length?'UF inválida: '+ufsInvalidas.join(', '):null;
const erroFiltroPesquisa=modoBuscaCompra ? (erroCompra??erroFiltroUasg) : (erroFiltroUasg??erroAlternativas??erroLocalidade??erroPrazo??erroTermos);

const limite=new Date();
limite.setDate(limite.getDate()+prazo);
const dataFinal=`${limite.getFullYear()}${String(limite.getMonth()+1).padStart(2,'0')}${String(limite.getDate()).padStart(2,'0')}`;

const ufsEntrada = ufsParametro;

let ufs = (ufsEntrada === undefined || ufsEntrada === null || ufsEntrada === '')
  ? []
  : lista(ufsEntrada).map(x => x.toUpperCase());

if (ufs.some(x => ['TODAS', 'BR', '*'].includes(x))) {
  ufs = TODAS_UFS;
}

ufs = [...new Set(ufs.filter(x => TODAS_UFS.includes(x)))];


// Com UASG, consulta diretamente a unidade e o CNPJ do órgão, sem parâmetro uf.
// Sem UASG, usa apenas as UFs explicitamente informadas.
if(uasgs.length && !erroFiltroUasg) ufs=[null];

const modalidades=[
  {codigoModalidade:6,modalidadeConsulta:'Pregão - Eletrônico'},
  {codigoModalidade:7,modalidadeConsulta:'Pregão - Presencial'},
  {codigoModalidade:8,modalidadeConsulta:'Dispensa'}
];

const config={
  iniciadoEmMs,
  prazo:modoBuscaCompra?null:prazo,
  uasgs,
  modoBuscaCompra,
  numeroCompra:modoBuscaCompra?numeroCompra:null,
  erroFiltroUasg,
  erroFiltroPesquisa,
  scoreMinimo:5,
  termosFortes,
  termosContextuais,
  contextosTecnologicos,
  termosExclusao,
  score:{
    termoForte:10,
    termoContextualComContexto:5,
    termoExclusao:-8
  }
};

if(erroFiltroPesquisa)return [{json:{config}}];
if(modoBuscaCompra)return idsCompra.map(idCompraConsulta=>({json:{tipoItem:'buscar_compra_exata',idCompraConsulta,config}}));


// Resolve UASGs em nós HTTP fora do Task Runner.
if(uasgs.length)return uasgs.map(uasg=>({json:{tipoItem:'resolver_uasg',uasgConsulta:uasg,dataFinal,config,modalidades}}));
const grupos=ufs.map(uf=>({uf}));

const out=[];
for(const grupo of grupos){
  for(const m of modalidades){
    out.push({json:{
      ...grupo,
      codigoModalidade:m.codigoModalidade,
      modalidadeConsulta:m.modalidadeConsulta,
      dataFinal,
      config
    }});
  }
}
return out;

const out=[];

// O input já está filtrado; os metadados originais vêm do nó de interpretação.
const filtradasPagina1=$input.all();
const interpretadas=$items('Interpretar página');
const interromper=filtradasPagina1.some(f=>Boolean(f.json.erroApiPncp));

for(let i=0;i<interpretadas.length;i++){
  const x=interpretadas[i].json;
  const f1=filtradasPagina1[i]?.json??null;

  const total=Math.max(1,Number(x.payload?.totalPaginas??1));
  const atual=Math.max(1,Number(x.payload?.numeroPagina??1));

  // Item marcador: garante que o loop tenha uma execução mesmo quando só existe página 1.
  // Não consulta o PNCP novamente; será tratado no node "Preparar item do loop".
  out.push({json:{
    tipoItem:'pagina1_cache',
    uf:x.uf,
    cnpj:x.cnpj,
    uasgConsulta:x.uasgConsulta,
    codigoModalidade:x.codigoModalidade,
    modalidadeConsulta:x.modalidadeConsulta,
    dataFinal:x.dataFinal,
    config:x.config,
    pagina:1,
    pagina1Filtrada:f1
  }});

  if(interromper || x.erroApiPncp || f1?.erroApiPncp)continue;

  for(let pagina=atual+1; pagina<=total; pagina++){
    out.push({json:{
      tipoItem:'consultar',
      uf:x.uf,
      cnpj:x.cnpj,
      uasgConsulta:x.uasgConsulta,
      codigoModalidade:x.codigoModalidade,
      modalidadeConsulta:x.modalidadeConsulta,
      dataFinal:x.dataFinal,
      config:x.config,
      pagina,
      pagina1Filtrada:f1
    }});
  }
}

return out;

function parse(v){
  if(v?.error||v?.errorMessage){
    const erro=v.error??v;
    const detalhe=String(typeof erro==='string'?erro:erro.message??v.errorMessage??JSON.stringify(erro));
    const status=Number(erro.statusCode??erro.httpCode??v.httpCode??0);
    return {payload:{data:[],numeroPagina:1,totalPaginas:1},erro:{tipo:status===429||/429|limite de requisi/i.test(detalhe)?'limite_requisicoes_excedido':'erro_conexao_pncp',codigo:String(status||erro.code||'HTTP'),mensagem:detalhe}};
  }

  // Quando o HTTP Request esgota os retries com 'Continue', o n8n entrega o erro como item.
  const msg = String(v?.error?.message ?? v?.errorMessage ?? v?.message ?? '');
  const code = String(v?.error?.code ?? v?.httpCode ?? v?.code ?? '');
  const textoErro = `${msg} ${code}`;
  if (/ECONNRESET|connection to the server was closed unexpectedly|socket hang up/i.test(textoErro)) {
    return {
      payload:{data:[],numeroPagina:1,totalPaginas:1},
      erro:{
        tipo:'erro_conexao_pncp',
        codigo:'ECONNRESET',
        mensagem:'A conexão com o PNCP foi encerrada inesperadamente após as tentativas automáticas.'
      }
    };
  }

  let raw=v;
  if(v&&typeof v==='object'&&!Array.isArray(v)){
    if(typeof v.data==='string') raw=v.data;
    else if(typeof v.body==='string') raw=v.body;
  }
  if(typeof raw==='string'){
    if(/limite de requisi(?:ç|c)(?:õ|o)es excedido/i.test(raw)){
      return {payload:{data:[],numeroPagina:1,totalPaginas:1},erro:{tipo:'limite_requisicoes_excedido',codigo:'RATE_LIMIT',mensagem:'O PNCP bloqueou a consulta por excesso de requisições. A pesquisa foi interrompida.',amostra:raw.slice(0,1000)}};
    }
    try{return {payload:JSON.parse(raw),erro:null};}
    catch(e){return {payload:{data:[]},erro:{tipo:'resposta_nao_json',mensagem:e.message,amostra:raw.slice(0,500)}};}
  }
  return {payload:(raw&&typeof raw==='object'?raw:{data:[]}),erro:null};
}

const entradas=$input.all();
// Saída false do IF na iteração atual, evitando reutilizar a primeira tarefa.
const tarefas=$items('Preparar item do loop',1);
const out=[];

for(let i=0;i<entradas.length;i++){
  const tarefa=tarefas[i]?.json??{};
  const p=parse(entradas[i].json);
  out.push({json:{...tarefa,payload:p.payload,erroApiPncp:p.erro},pairedItem:{item:i}});
}
return out;

function obterUasg(r){
  // A fonte Compras.gov.br é verificada antes de aplicar o filtro.
  const unidade=String(r.unidadeOrgao?.codigoUnidade??r.unidadeOrgaoCodigoUnidade??'').trim();
  if(/^\d{6}$/.test(unidade))return unidade;
  const id=String(r.idCompra??'').trim();
  if(/^\d{17}$/.test(id))return id.slice(0,6);
  const origem=String(r.linkSistemaOrigem??'');
  if(/^https?:\/\/cnetmobile\.estaleiro\.serpro\.gov\.br\//i.test(origem)){
    const compra=origem.match(/[?&](?:amp;)?compra=(\d{17})(?!\d)/i)?.[1];
    if(compra)return compra.slice(0,6);
  }
  return null;
}
function norm(v){
  return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^\p{L}\p{N}\s:/.-]+/gu,' ').replace(/\s+/g,' ').trim();
}
function esc(v){return v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function tem(texto,termo){
  const t=norm(termo); if(!t)return false;
  return new RegExp(`(^|[^a-z0-9])${esc(t).replace(/\s+/g,'\\s+')}([^a-z0-9]|$)`,'i').test(texto);
}
function dt(v){if(!v)return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d;}


const saida=[];

for(const item of $input.all()){
  const x=item.json;
  const payload=x.payload??{};
  const config=x.config??{};
  const registros=Array.isArray(payload.data)?payload.data:[];
  const filtroUasgs=new Set(config.uasgs??[]);

  const fortes=(config.termosFortes??[]).map(norm);
  const contextuais=(config.termosContextuais??[]).map(norm);
  const contextos=(config.contextosTecnologicos??[]).map(norm);
  const exclusoes=(config.termosExclusao??[]).map(norm);

  const agora=new Date();
  const limite=new Date(agora);
  limite.setDate(limite.getDate()+Number(config.prazo));

  const diag={paginas:1,recebidos:registros.length,naoTIC:0,scoreInsuficiente:0,prazo:0,status:0,fonteNaoPermitida:0,excluidos:0,uasgNaoPermitida:0,contratacoesComItensConsultados:0,requisicoesItens:0,aprovadosPelosItens:0,falhasConsultaItens:0,aprovados:0};
  const aprovados=[];

  for(const r of registros){
    // Fonte da publicação no PNCP: aceitar somente Compras.gov.br.
    // Fonte ausente também é rejeitada; links não substituem a identificação da fonte.
    const fonte=String(r.usuarioNome??'').trim().toLowerCase();
    if(fonte!=='compras.gov.br'){diag.fonteNaoPermitida++;continue;}
    const uasg=obterUasg(r);
    if(filtroUasgs.size && !filtroUasgs.has(uasg)){diag.uasgNaoPermitida++;continue;}
    if(r.contratacaoExcluida===true){diag.excluidos++;continue;}

    const situacao=norm(r.situacaoCompraNome??r.situacaoNome??r.situacao??'');
    const bloqueados=['suspensa','suspenso','vencida','vencido','revogada','revogado','anulada','anulado','cancelada','cancelado','encerrada','encerrado','deserta','deserto','fracassada','fracassado'];
    if(bloqueados.some(v=>situacao.includes(v))){diag.status++;continue;}

    const fim=dt(r.dataEncerramentoProposta);
    if(!fim||fim<=agora||fim>limite){diag.prazo++;continue;}


    function avaliar(texto){
      const tf=fortes.filter(t=>tem(texto,t));
      const tc=contextuais.filter(t=>tem(texto,t));
      const cx=contextos.filter(t=>tem(texto,t));
      const ex=exclusoes.filter(t=>tem(texto,t));
      let score=tf.length*Number(config.score?.termoForte??10);
      if(tc.length&&cx.length)score+=Number(config.score?.termoContextualComContexto??5);
      score+=ex.length*Number(config.score?.termoExclusao??-8);
      return {score,palavras:[...new Set([...tf,...tc,...cx])]};
    }
    const texto=norm([r.objetoCompra,r.informacaoComplementar,r.justificativaPresencial].filter(Boolean).join(' '));
    const avaliacaoObjeto=avaliar(texto);
    let score=avaliacaoObjeto.score;
    let palavras=avaliacaoObjeto.palavras;
    let itensTICEncontrados=[];
    let origemClassificacaoTIC='objeto';
    if(score<Number(config.scoreMinimo??5)){diag.naoTIC++;diag.scoreInsuficiente++;continue;}

    aprovados.push({...r,
      uasg,
      ufConsulta:item.json.uf,
      codigoModalidadeConsulta:item.json.codigoModalidade,
      modalidadeConsulta:item.json.modalidadeConsulta,
      scoreRelevancia:score,
      palavrasChaveEncontradas:palavras,
      origemClassificacaoTIC,
      itensTICEncontrados,
      diasRestantes:Number(((fim-agora)/86400000).toFixed(2))
    });
    diag.aprovados++;
  }

  const erroApiPncp=item.json.erroApiPncp??null;
  const popupErro=erroApiPncp
    ? {
        exibir:true,
        tipo:erroApiPncp.tipo,
        titulo:erroApiPncp.tipo==='erro_consulta_itens' ? 'Falha ao consultar itens do PNCP' : erroApiPncp.tipo==='limite_requisicoes_excedido' ? 'Limite de requisições excedido no PNCP' : erroApiPncp.tipo==='erro_conexao_pncp' ? 'Falha de conexão com o PNCP' : 'Erro na consulta ao PNCP',
        mensagem:erroApiPncp.tipo==='erro_consulta_itens'
          ? 'Não foi possível verificar os itens de uma contratação. A pesquisa foi interrompida para não apresentar um resultado incompleto como definitivo.'
          : erroApiPncp.tipo==='limite_requisicoes_excedido'
          ? 'O PNCP bloqueou a consulta por excesso de requisições. A pesquisa foi interrompida para não continuar enviando solicitações. Aguarde antes de tentar novamente.'
          : erroApiPncp.tipo==='erro_conexao_pncp'
          ? 'A conexão com o servidor do PNCP foi encerrada inesperadamente. As tentativas automáticas foram esgotadas. Aguarde alguns instantes e tente novamente.'
          : 'O PNCP retornou uma resposta inválida ou não-JSON. Tente novamente em alguns instantes.',
        detalhe:erroApiPncp.mensagem??null,
        codigo:erroApiPncp.codigo??null,
        amostra:erroApiPncp.amostra??null
      }
    : null;

  saida.push({json:{
    uf:item.json.uf,
    codigoModalidade:item.json.codigoModalidade,
    modalidadeConsulta:item.json.modalidadeConsulta,
    pagina:Number(payload.numeroPagina??item.json.pagina??1),
    totalPaginas:Number(payload.totalPaginas??1),
    erroApiPncp,
    popupErro,
    diagnostico:diag,
    config,
    registros:aprovados
  }});
}

return saida;

const paginas=$input.all();
const vistos=new Set();
const oportunidades=[];
let popupErro=null;

const diagnostico={
  paginas:0,recebidos:0,naoTIC:0,scoreInsuficiente:0,prazo:0,status:0,
  fonteNaoPermitida:0,excluidos:0,uasgNaoPermitida:0,aprovadosAntesDedup:0,duplicados:0
};

for(const p of paginas){
  if(!popupErro && p.json.popupErro?.exibir===true){
    popupErro=p.json.popupErro;
  }

  const d=p.json.diagnostico??{};
  diagnostico.paginas+=Number(d.paginas??0);
  diagnostico.recebidos+=Number(d.recebidos??0);
  diagnostico.naoTIC+=Number(d.naoTIC??0);
  diagnostico.scoreInsuficiente+=Number(d.scoreInsuficiente??0);
  diagnostico.prazo+=Number(d.prazo??0);
  diagnostico.status+=Number(d.status??0);
  diagnostico.fonteNaoPermitida+=Number(d.fonteNaoPermitida??0);
  diagnostico.excluidos+=Number(d.excluidos??0);
  diagnostico.uasgNaoPermitida+=Number(d.uasgNaoPermitida??0);
  diagnostico.aprovadosAntesDedup+=Number(d.aprovados??0);

  for(const r of (p.json.registros??[])){
    const chave=r.numeroControlePNCP || r.idCompra ||
      [r.orgaoEntidade?.cnpj,r.anoCompra,r.sequencialCompra].filter(Boolean).join('-');

    if(chave && vistos.has(chave)){
      diagnostico.duplicados++;
      continue;
    }
    if(chave) vistos.add(chave);
    oportunidades.push(r);
  }
}

oportunidades.sort((a,b)=>
  Number(b.scoreRelevancia??0)-Number(a.scoreRelevancia??0) ||
  new Date(a.dataEncerramentoProposta??'2999-12-31')-
  new Date(b.dataEncerramentoProposta??'2999-12-31')
);

return [{json:{diagnostico,oportunidades,popupErro}}];

const pacote=$json;
const tempoAnaliseSegundos=Number(((Date.now()-$('Configurar pesquisa').first().json.config.iniciadoEmMs)/1000).toFixed(2));
const diagnostico=pacote.diagnostico??{};
const oportunidades=pacote.oportunidades??[];
const popupErro=pacote.popupErro??null;
const configBusca=$('Configurar pesquisa').first().json.config;

if(popupErro?.exibir===true){
  return [{json:{
    tempoAnaliseSegundos,
    tipoSaida:'erro',
    encontrouOportunidades:false,
    popup:true,
    titulo:popupErro.titulo??'Erro na consulta ao PNCP',
    mensagem:popupErro.mensagem??'O PNCP retornou uma resposta inválida.',
    tipoErro:popupErro.tipo??'resposta_nao_json',
    detalhe:popupErro.detalhe??null,
    amostra:popupErro.amostra??null,
    diagnostico
  }}];
}

function moeda(v){
  if(v===null||v===undefined||v===''||Number(v)===0)return 'Sigiloso';
  return Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
}

if(!oportunidades.length){
  return [{json:{
    tempoAnaliseSegundos,
    tipoSaida:'resumo',
    encontrouOportunidades:false,
    diagnostico,
    ...(configBusca.modoBuscaCompra?{mensagem:`Compra ${configBusca.numeroCompra} nao encontrada para a UASG ${configBusca.uasgs.join(', ')}.`}: {})
  }}];
}

function idCompraComprasGov(r){
  // Reutiliza o identificador do sistema de origem; o número PNCP é diferente.
  for(const texto of [r.linkSistemaOrigem,r.informacaoComplementar]){
    const urls=String(texto??'').match(/https?:\/\/cnetmobile\.estaleiro\.serpro\.gov\.br\/[^\s<>"']*/gi)??[];
    for(const url of urls){
      const id=url.match(/[?&](?:amp;)?compra=(\d{17})(?!\d)/i)?.[1];
      if(id)return id;
    }
  }
  const id=String(r.idCompra??'').trim();
  return /^\d{17}$/.test(id)?id:null;
}

return oportunidades.map(r=>{
  const idCompraOrigem=idCompraComprasGov(r);
